css:
.supermutant-desc-mobile{display:none}
@media (max-width: 767.98px){.supermutant-desc-mobile{display:block}.supermutant-desc-original{display:none}}
/* ОСОБЕННОСТИ/ИНВЕНТАРЬ: заголовки — как шапка таблицы АТАКИ */
#sppb-addon-b9917d63-6 .sppb-addon-title,
#sppb-addon-878d886e-1 .sppb-addon-title{font-size:1rem;line-height:1.5;padding:6px 0}
/* текст особенностей и инвентаря — того же размера, что и в ячейках таблиц */
#sppb-addon-d1d0a1ed-0 .sppb-addon-content,
#sppb-addon-b6817113-6 .sppb-addon-content,
#sppb-addon-8cb14d9b-7 .sppb-addon-content,
#sppb-addon-70dad39f-d .sppb-addon-content{font-size:1rem;line-height:1.5}
@media (max-width: 767.98px){
  /* убираем вложенные отступы, из-за которых SPECIAL/НАВЫКИ были уже остальных */
  #section-2509769e-8 > .sppb-row-container,
  #section-2509769e-8 .sppb-row,
  #section-2509769e-8 .sppb-column{padding-left:0;padding-right:0;margin-left:0;margin-right:0}
  /* у блока АТАКИ убираем боковые 20px — таблица становится той же ширины */
  #sppb-addon-fda8f949-c{padding-left:0;padding-right:0}
  /* все таблицы — по ширине правой колонки */
  .sppb-addon-content table{width:100%}
  /* особенности и инвентарь — та же ширина, с видимой рамкой */
  #sppb-addon-d1d0a1ed-0,
  #sppb-addon-b6817113-6,
  #sppb-addon-8cb14d9b-7,
  #sppb-addon-70dad39f-d{border:1px solid #757575;box-sizing:border-box}
}
